mapper.select:
SELECT  FROM sms_inbox
WHERE user_id = #{userId} AND status = 'PENDING' AND created_at >= #{since}
ORDER BY tx_date DESC, tx_time DESC, id DESC

SELECT id, transaction_date AS date, memo FROM daily_transaction
WHERE user_id = #{userId} AND type = 'EXPENSE' AND amount = #{amount}
  AND transaction_date >= #{from} AND transaction_date <= #{to}
ORDER BY (memo IS NOT NULL AND #{merchant} IS NOT NULL AND memo LIKE CONCAT('%', #{merchant}, '%')) DESC,
         transaction_date DESC, id DESC
LIMIT 1
